-- Initial independent Meena's Nest schema. See subsequent migrations for stricter owner insert policy and RPCs.
create schema if not exists private;
create extension if not exists pgcrypto with schema extensions;
create or replace function private.set_updated_at() returns trigger language plpgsql set search_path = '' as $$ begin new.updated_at:=now(); return new; end; $$;
create table public.workspaces(id uuid primary key default gen_random_uuid(),name text not null check(char_length(trim(name)) between 2 and 80),owner_user_id uuid not null references auth.users(id) on delete restrict,created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.workspace_members(workspace_id uuid not null references public.workspaces(id) on delete restrict,user_id uuid not null references auth.users(id) on delete restrict,role text not null default 'partner' check(role in ('owner','partner')),created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,primary key(workspace_id,user_id));
create table public.workspace_invites(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete restrict,invited_email text not null check(invited_email=lower(trim(invited_email))),token_hash text not null unique,role text not null default 'partner' check(role='partner'),invited_by uuid not null references auth.users(id) on delete restrict,expires_at timestamptz not null,accepted_at timestamptz,created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.pregnancy_profiles(id uuid primary key default gen_random_uuid(),workspace_id uuid not null unique references public.workspaces(id) on delete restrict,created_by uuid not null references auth.users(id) on delete restrict,lmp_date date,due_date date,baby_name text check(baby_name is null or char_length(baby_name)<=80),notes text check(notes is null or char_length(notes)<=4000),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,constraint pregnancy_dates_reasonable check(lmp_date is null or due_date is null or due_date between lmp_date+230 and lmp_date+310));
create table public.vault_documents(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete restrict,created_by uuid not null references auth.users(id) on delete restrict,title text not null check(char_length(trim(title)) between 1 and 140),category text not null default 'other' check(category in ('scan','lab_report','prescription','insurance','discharge_summary','other')),file_name text not null check(char_length(file_name) between 1 and 255),storage_path text not null unique,mime_type text not null check(mime_type in ('application/pdf','image/jpeg','image/png','image/webp')),size_bytes bigint not null check(size_bytes between 1 and 10485760),document_date date,notes text check(notes is null or char_length(notes)<=2000),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,constraint vault_documents_id_workspace_unique unique(id,workspace_id));
create table public.expenses(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete restrict,created_by uuid not null references auth.users(id) on delete restrict,expense_date date not null default current_date,amount numeric(12,2) not null check(amount>0 and amount<=99999999.99),currency char(3) not null default 'INR' check(currency='INR'),category text not null check(category in ('consultation','scan','lab_test','medicine','travel','nutrition','baby_items','insurance','other')),merchant text check(merchant is null or char_length(merchant)<=140),description text check(description is null or char_length(description)<=1000),document_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,constraint expenses_document_same_workspace foreign key(document_id,workspace_id) references public.vault_documents(id,workspace_id) on delete restrict);
create or replace function private.is_workspace_member(p_workspace_id uuid) returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.workspace_members wm where wm.workspace_id=p_workspace_id and wm.user_id=(select auth.uid()) and wm.deleted_at is null); $$;
create or replace function private.is_workspace_owner(p_workspace_id uuid) returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.workspace_members wm where wm.workspace_id=p_workspace_id and wm.user_id=(select auth.uid()) and wm.role='owner' and wm.deleted_at is null); $$;
create or replace function private.accept_workspace_invite(p_token text) returns uuid language plpgsql security definer set search_path = '' as $$
declare v_user_id uuid:=auth.uid(); v_email text; v_workspace_id uuid; v_invite public.workspace_invites%rowtype;
begin
 if v_user_id is null or p_token is null or length(p_token)<32 then raise exception 'Invalid or expired invitation'; end if;
 select lower(u.email) into v_email from auth.users u where u.id=v_user_id;
 if v_email is null then raise exception 'An authenticated email address is required'; end if;
 select wi.* into v_invite from public.workspace_invites wi where wi.token_hash=encode(extensions.digest(convert_to(p_token,'UTF8'),'sha256'),'hex') and wi.invited_email=v_email and wi.accepted_at is null and wi.deleted_at is null and wi.expires_at>now() for update;
 if not found then raise exception 'Invalid or expired invitation'; end if;
 insert into public.workspace_members(workspace_id,user_id,role,created_by) values(v_invite.workspace_id,v_user_id,'partner',v_invite.invited_by) on conflict(workspace_id,user_id) do update set deleted_at=null,updated_at=now(),role='partner';
 update public.workspace_invites set accepted_at=now(),updated_at=now() where id=v_invite.id;
 v_workspace_id:=v_invite.workspace_id; return v_workspace_id;
end; $$;
create or replace function private.is_member_folder(p_folder text) returns boolean language plpgsql stable security definer set search_path = '' as $$ begin return private.is_workspace_member(p_folder::uuid); exception when invalid_text_representation then return false; end; $$;
revoke all on schema private from public,anon; grant usage on schema private to authenticated;
revoke all on function private.is_workspace_member(uuid) from public,anon; revoke all on function private.is_workspace_owner(uuid) from public,anon; revoke all on function private.accept_workspace_invite(text) from public,anon; revoke all on function private.is_member_folder(text) from public,anon;
grant execute on function private.is_workspace_member(uuid) to authenticated; grant execute on function private.is_workspace_owner(uuid) to authenticated; grant execute on function private.accept_workspace_invite(text) to authenticated; grant execute on function private.is_member_folder(text) to authenticated;
do $$ declare t text; begin foreach t in array array['workspaces','workspace_members','workspace_invites','pregnancy_profiles','vault_documents','expenses'] loop execute format('create trigger %I_set_updated_at before update on public.%I for each row execute function private.set_updated_at()',t,t); end loop; end $$;
alter table public.workspaces enable row level security; alter table public.workspace_members enable row level security; alter table public.workspace_invites enable row level security; alter table public.pregnancy_profiles enable row level security; alter table public.vault_documents enable row level security; alter table public.expenses enable row level security;
create policy workspaces_select_member_or_owner on public.workspaces for select to authenticated using(deleted_at is null and (owner_user_id=(select auth.uid()) or private.is_workspace_member(id)));
create policy workspaces_insert_owner on public.workspaces for insert to authenticated with check(owner_user_id=(select auth.uid()) and created_by=(select auth.uid()));
create policy workspaces_update_owner on public.workspaces for update to authenticated using(owner_user_id=(select auth.uid()) and deleted_at is null) with check(owner_user_id=(select auth.uid()));
create policy workspace_members_select on public.workspace_members for select to authenticated using(private.is_workspace_member(workspace_id) and deleted_at is null);
create policy workspace_members_insert_owner_self on public.workspace_members for insert to authenticated with check(user_id=(select auth.uid()) and created_by=(select auth.uid()) and exists(select 1 from public.workspaces w where w.id=workspace_id and w.owner_user_id=(select auth.uid())));
create policy workspace_invites_select_owner on public.workspace_invites for select to authenticated using(private.is_workspace_owner(workspace_id) and deleted_at is null);
create policy workspace_invites_insert_owner on public.workspace_invites for insert to authenticated with check(private.is_workspace_owner(workspace_id) and invited_by=(select auth.uid()) and created_by=(select auth.uid()));
create policy workspace_invites_update_owner on public.workspace_invites for update to authenticated using(private.is_workspace_owner(workspace_id) and deleted_at is null) with check(private.is_workspace_owner(workspace_id));
create policy pregnancy_profiles_select_member on public.pregnancy_profiles for select to authenticated using(private.is_workspace_member(workspace_id) and deleted_at is null);
create policy pregnancy_profiles_insert_member on public.pregnancy_profiles for insert to authenticated with check(private.is_workspace_member(workspace_id) and created_by=(select auth.uid()));
create policy pregnancy_profiles_update_member on public.pregnancy_profiles for update to authenticated using(private.is_workspace_member(workspace_id) and deleted_at is null) with check(private.is_workspace_member(workspace_id));
create policy vault_documents_select_member on public.vault_documents for select to authenticated using(private.is_workspace_member(workspace_id) and deleted_at is null);
create policy vault_documents_insert_member on public.vault_documents for insert to authenticated with check(private.is_workspace_member(workspace_id) and created_by=(select auth.uid()));
create policy vault_documents_update_member on public.vault_documents for update to authenticated using(private.is_workspace_member(workspace_id) and deleted_at is null) with check(private.is_workspace_member(workspace_id));
create policy expenses_select_member on public.expenses for select to authenticated using(private.is_workspace_member(workspace_id) and deleted_at is null);
create policy expenses_insert_member on public.expenses for insert to authenticated with check(private.is_workspace_member(workspace_id) and created_by=(select auth.uid()));
create policy expenses_update_member on public.expenses for update to authenticated using(private.is_workspace_member(workspace_id) and deleted_at is null) with check(private.is_workspace_member(workspace_id));
grant select,insert,update on public.workspaces to authenticated; grant select,insert on public.workspace_members to authenticated; grant select,insert,update on public.workspace_invites to authenticated; grant select,insert,update on public.pregnancy_profiles to authenticated; grant select,insert,update on public.vault_documents to authenticated; grant select,insert,update on public.expenses to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('pregnancy-vault','pregnancy-vault',false,10485760,array['application/pdf','image/jpeg','image/png','image/webp']) on conflict(id) do update set public=false,file_size_limit=10485760,allowed_mime_types=array['application/pdf','image/jpeg','image/png','image/webp'];
create policy pregnancy_vault_select_member on storage.objects for select to authenticated using(bucket_id='pregnancy-vault' and private.is_member_folder((storage.foldername(name))[1]));
create policy pregnancy_vault_insert_member on storage.objects for insert to authenticated with check(bucket_id='pregnancy-vault' and private.is_member_folder((storage.foldername(name))[1]));
create policy pregnancy_vault_update_member on storage.objects for update to authenticated using(bucket_id='pregnancy-vault' and private.is_member_folder((storage.foldername(name))[1])) with check(bucket_id='pregnancy-vault' and private.is_member_folder((storage.foldername(name))[1]));
create policy pregnancy_vault_delete_member on storage.objects for delete to authenticated using(bucket_id='pregnancy-vault' and private.is_member_folder((storage.foldername(name))[1]));
